// src/ChatBot.js
import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import styled from "styled-components";
import { FaPaperPlane } from "react-icons/fa";

const ChatContainer = styled.div`
  display: flex;
  justify-content: center;s
  align-items: center;
  height: 100vh;
  background-color: #343541;
  padding: 20px;
`;

const ChatWrapper = styled.div`
  background-color: #444654;
  padding: 20px;
  border-radius: 10px;
  width: 100%;
  max-width: 800px;
  height: 80vh;
  display: flex;
  flex-direction: column;
`;

const MessageContainer = styled.div`
  flex-grow: 1;
  padding: 10px;
  overflow-y: auto;
  border-bottom: 1px solid #565869;
`;

const Message = styled.div`
  margin: 10px 0;
  display: flex;
  justify-content: ${({ user }) => (user ? "flex-end" : "flex-start")};

  p {
    max-width: 70%;
    padding: 10px;
    border-radius: 10px;
    background-color: ${({ user }) => (user ? "#056162" : "#343541")};
    color: #fff;
  }
`;

const InputContainer = styled.div`
  display: flex;
  align-items: center;
  padding: 10px;
`;

const Input = styled.input`
  flex-grow: 1;
  padding: 10px;
  border-radius: 5px;
  border: 1px solid #565869;
  background-color: #3b3d45;
  color: #fff;
  outline: none;

  &:focus {
    border-color: #565869;
  }
`;

const Button = styled.button`
  background: none;
  border: none;
  margin-left: 10px;
  color: #565869;
  cursor: pointer;
  font-size: 20px;
  transition: color 0.3s;

  &:hover {
    color: #fff;
  }
`;

const ChatBot = () => {
  const location = useLocation();
  const { response, age, occupation, tobacco, coverage } = location.state || {};
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");

  useEffect(() => {
    if (response) {
      setMessages([...messages, { text: response, user: false }]);
    }
  }, [response]);

  const handleSend = () => {
    if (input.trim()) {
      setMessages([...messages, { text: input, user: true }]);
      setInput("");
      // Simulate bot response
      setTimeout(() => {
        setMessages((prevMessages) => [
          ...prevMessages,
          { text: `You said: ${input}`, user: false },
        ]);
      }, 500);
    }
  };

  return (
    <ChatContainer>
      <ChatWrapper>
        <MessageContainer>
          {messages.map((msg, index) => (
            <Message key={index} user={msg.user}>
              <p>{msg.text}</p>
            </Message>
          ))}
        </MessageContainer>
        <InputContainer>
          <Input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Type a message..."
          />
          <Button onClick={handleSend}>
            <FaPaperPlane />
          </Button>
        </InputContainer>
      </ChatWrapper>
    </ChatContainer>
  );
};

export default ChatBot;
